public static NashornSandbox create() {
		return new NashornSandboxImpl();
	}

PoisonPil(final Pattern pattern, final String replacement) {
			this.pattern = pattern;
			this.replacement = replacement;
		}

@Override
			public boolean removeEldestEntry(final Map.Entry<String, String> eldest) {
				return size() > maxPreparedStatements;
			}

JsEvaluator(final ScriptEngine scriptEngine, final long maxCPUTime, final long maxMemory, ScriptEngineOperation operation) {
    this.scriptEngine = scriptEngine;
    this.threadMonitor = new ThreadMonitor(maxCPUTime, maxMemory);
    this.operation = operation;
  }

boolean isCPULimitExceeded() {
    return threadMonitor.isCPULimitExceeded();
  }

boolean isMemoryLimitExceeded() {
    return threadMonitor.isMemoryLimitExceeded();
  }

void runMonitor() {
    threadMonitor.run();
  }

@Override
  public void run() {
    try {
      threadMonitor.setThreadToMonitor(Thread.currentThread());
      result = operation.executeScriptEngineOperation(scriptEngine);
    } 
    catch (final RuntimeException e) {
      // InterruptedException means script was successfully interrupted,
      // so no exception should be propagated
      if(!(e.getCause() instanceof InterruptedException)) {
        exception = e;
      }
    }
    catch (final Exception e) {
      exception = e;
    } 
    finally {
      threadMonitor.scriptFinished();
      threadMonitor.stopMonitor();
    }
  }

Exception getException() {
    return exception;
  }

Object getResult() {
    return result;
  }

PoisonPil(final Pattern pattern, final String replacement) {
			this.pattern = pattern;
			this.replacement = replacement;
		}

private void assertScriptEngine() {
		try {
			scriptEngine.eval("var window = {};");
			scriptEngine.eval(getBeautifyJs());
		} catch (final Exception e) {
			throw new RuntimeException(e);
		}
	}

private static ScriptObjectMirror getBeautifHandler(final ScriptEngine scriptEngine) {
		try {
			for (final String name : BEAUTIFY_FUNCTIONS) {
				final Object somWindow = scriptEngine.eval(name);
				if (somWindow != null) {
					return (ScriptObjectMirror) somWindow;
				}
			}
			throw new RuntimeException("Cannot find function 'js_beautify' in: window, exports, global");
		} catch (final ScriptException e) {
			// should never happen
			throw new RuntimeException(e);
		}
	}

private SecuredJsCache createSecuredJsCache(final int maxPreparedStatements) {
		// Create cache
		if (maxPreparedStatements == 0) {
			return null;
		} else {
			return newSecuredJsCache(maxPreparedStatements);
		}
	}

private SecuredJsCache newSecuredJsCache(final int maxPreparedStatements) {
		final LinkedHashMap<String, String> linkedHashMap = new LinkedHashMap<String, String>(maxPreparedStatements + 1, .75F, true) {
			private static final long serialVersionUID = 1L;

			// This method is called just after a new entry has been added
			@Override
			public boolean removeEldestEntry(final Map.Entry<String, String> eldest) {
				return size() > maxPreparedStatements;
			}
		};
		return new LinkedHashMapSecuredJsCache(linkedHashMap, allowNoBraces);
	}

void checkBraces(final String beautifiedJs) throws BracesException {
		if (allowNoBraces) {
			return;
		}

		for (final Pattern pattern : LACK_EXPECTED_BRACES) {
			final Matcher matcher = pattern.matcher(RemoveComments.perform(beautifiedJs));
			if (matcher.find()) {

				String line = "";
				int index = matcher.start();
				while (index >= 0 && beautifiedJs.charAt(index) != '\n' ) {
					line = beautifiedJs.charAt(index)+line;
					index--;
				}

				int singleParaCount = line.length() - line.replace("'", "").length();
				int doubleParaCount = line.length() - line.replace("\"", "").length();

				if (singleParaCount % 2 != 0 || doubleParaCount % 2 != 0) {
					// for in string

				} else {
					throw new BracesException("No block braces after function|for|while|do. Found ["+matcher.group()+"]");
				}
			}
		}
	}

String injectInterruptionCalls(final String str) {
		String current = str;
		for (final PoisonPil pp : POISON_PILLS) {
			final StringBuffer sb = new StringBuffer();
			final Matcher matcher = pp.pattern.matcher(current);
			while (matcher.find()) {
				matcher.appendReplacement(sb, ("$1" + pp.replacement));
			}
			matcher.appendTail(sb);
			current = sb.toString();
		}
		return current;
	}

private String getPreamble() {
		final String clazzName = InterruptTest.class.getName();
		final StringBuilder sb = new StringBuilder();
		sb.append("var ").append(JS_INTERRUPTED_TEST).append("=Java.type('").append(clazzName).append("');");
		sb.append("var ").append(JS_INTERRUPTED_FUNCTION).append("=function(){");
		sb.append(JS_INTERRUPTED_TEST).append(".test();};\n");
		return sb.toString();
	}

private void checkJs(final String js) {
		if (js.contains(JS_INTERRUPTED_FUNCTION) || js.contains(JS_INTERRUPTED_TEST)) {
			throw new IllegalArgumentException(
					"Script contains the illegal string [" + JS_INTERRUPTED_TEST + "," + JS_INTERRUPTED_FUNCTION + "]");
		}
	}

String secureJs(final String js) throws ScriptException {
		if (securedJsCache == null) {
			return secureJsImpl(js);
		}
		ScriptException[] ex = new ScriptException[1];
		String securedJs = securedJsCache.getOrCreate(js, allowNoBraces, ()->{
			try {
				return secureJsImpl(js);
			} catch (BracesException e) {
				ex[0] = e;
				return null;
			}
		});
		if (ex[0] != null) {
			throw ex[0];
		}
		return securedJs;
	}

private String secureJsImpl(final String js) throws BracesException {
		checkJs(js);
		final String beautifiedJs = beautifyJs(js);
		checkBraces(beautifiedJs);
		final String injectedJs = injectInterruptionCalls(beautifiedJs);
		// if no injection, no need to add preamble
		if (beautifiedJs.equals(injectedJs)) {
			return beautifiedJs;
		} else {
			final String preamble = getPreamble();
			return preamble + injectedJs;
		}
	}

String beautifyJs(final String js) {
		return (String) jsBeautify.call("beautify", js, BEAUTIFY_OPTIONS);
	}

private static String getBeautifyJs() {
		String script = beautifysScript.get();
		if (script == null) {
			try (final BufferedReader reader = new BufferedReader(new InputStreamReader(
					new BufferedInputStream(JsSanitizer.class.getResourceAsStream(BEAUTIFY_JS)), "UTF-8"))) {
				final StringBuilder sb = new StringBuilder();
				String line;
				while ((line = reader.readLine()) != null) {
					sb.append(line).append('\n');
				}
				script = sb.toString();
			} catch (final IOException e) {
				throw new RuntimeException("Cannot find file: " + BEAUTIFY_JS, e);
			}
			beautifysScript = new SoftReference<>(script);
		}
		return script;
	}

ThreadMonitor(final long maxCPUTime, final long maxMemory) {
		this.maxMemory = maxMemory;
		this.maxCPUTime = maxCPUTime * 1000000;
		stop = new AtomicBoolean(false);
		scriptFinished = new AtomicBoolean(false);
		scriptKilled = new AtomicBoolean(false);
		cpuLimitExceeded = new AtomicBoolean(false);
		memoryLimitExceeded = new AtomicBoolean(false);
		monitor = new Object();
		threadBean = ManagementFactory.getThreadMXBean();
		// ensure this feature is enabled
		threadBean.setThreadCpuTimeEnabled(true);
		if (threadBean instanceof com.sun.management.ThreadMXBean) {
			memoryCouter = (com.sun.management.ThreadMXBean) threadBean;
			// ensure this feature is enabled
			memoryCouter.setThreadAllocatedMemoryEnabled(true);
		} else {
			if (maxMemory > 0) {
				throw new UnsupportedOperationException("JVM does not support thread memory counting");
			}
			memoryCouter = null;
		}
	}

private void reset() {
		stop.set(false);
		scriptFinished.set(false);
		scriptKilled.set(false);
		cpuLimitExceeded.set(false);
		threadToMonitor = null;
	}

@SuppressWarnings("deprecation")
	void run() {
		try {
			// wait, for threadToMonitor to be set in JS evaluator thread
			synchronized (monitor) {
				if (threadToMonitor == null) {
					monitor.wait(maxCPUTime / MILI_TO_NANO);
				}
			}
			if (threadToMonitor == null) {
				throw new IllegalStateException("Executor thread not set after " + maxCPUTime / MILI_TO_NANO + " ms");
			}
			final long startCPUTime = getCPUTime();
			final long startMemory = getCurrentMemory();
			while (!stop.get()) {
				final long runtime = getCPUTime() - startCPUTime;
				final long memory = getCurrentMemory() - startMemory;

				if (isCpuTimeExided(runtime) || isMemoryExided(memory)) {

					cpuLimitExceeded.set(isCpuTimeExided(runtime));
					memoryLimitExceeded.set(isMemoryExided(memory));
					threadToMonitor.interrupt();
					synchronized (monitor) {
						monitor.wait(50);
					}
					if (stop.get()) {
						return;
					}
					if (!scriptFinished.get()) {
						LOG.error(this.getClass().getSimpleName() + ": Thread hard shutdown!");
						threadToMonitor.stop();
						scriptKilled.set(true);
					}
					return;
				} else {

				}
				synchronized (monitor) {
					long waitTime = getCheckInterval(runtime);

					if (waitTime == 0) {
						waitTime = 1;
					}
					monitor.wait(waitTime);
				}

			}
		} catch (final Exception e) {
			throw new RuntimeException(e);
		}
	}

private long getCheckInterval(final long runtime) {
		if (maxCPUTime == 0) {
			return 10;
		}
		if (maxMemory == 0) {
			return Math.max((maxCPUTime - runtime) / MILI_TO_NANO, 5);
		}
		return Math.min((maxCPUTime - runtime) / MILI_TO_NANO, 10);
	}

private boolean isCpuTimeExided(final long runtime) {
		if (maxCPUTime == 0) {
			return false;
		}
		return runtime > maxCPUTime;
	}

private boolean isMemoryExided(final long memory) {
		if (maxMemory == 0) {
			return false;
		}
		return memory > maxMemory;
	}

private long getCurrentMemory() {
		if (maxMemory == 0 || memoryCouter != null) {
			return memoryCouter.getThreadAllocatedBytes(threadToMonitor.getId());
		}
		return 0L;
	}

private long getCPUTime() {
		return threadBean.getThreadCpuTime(threadToMonitor.getId());
	}

public void stopMonitor() {
		stop.set(true);
		notifyMonitorThread();
	}

public void setThreadToMonitor(final Thread t) {
		reset();
		threadToMonitor = t;
		notifyMonitorThread();
	}

public void scriptFinished() {
		scriptFinished.set(false);
	}

public boolean isCPULimitExceeded() {
		return cpuLimitExceeded.get();
	}

public boolean isMemoryLimitExceeded() {
		return memoryLimitExceeded.get();
	}

private void notifyMonitorThread() {
		synchronized (monitor) {
			monitor.notifyAll();
		}
	}

public NashornSandboxImpl() {
		this(new String[0]);
	}

public NashornSandboxImpl() {
		this(new String[0]);
	}

private void assertScriptEngine() {
        try {
            if (!engineAsserted) {
                produceSecureBindings();
            }
            else if (!engineBindingUnchanged()) {
                resetEngineBindings();
            }
        }
        catch (final Exception e) {
            throw new RuntimeException(e);
        }
    }

private boolean engineBindingUnchanged() {
        final Bindings current = scriptEngine.getBindings(ScriptContext.ENGINE_SCOPE);
        for (Map.Entry<String, Object> e : cached.entrySet()) {
            if (!current.containsKey(e.getKey()) || !Objects.equals(current.get(e.getKey()), e.getValue())) {
                return false;
            }
        }
        return true;
    }

private void produceSecureBindings() {
        try {
            if (!engineAsserted) {
                final StringBuilder sb = new StringBuilder();
                cached = scriptEngine.getBindings(ScriptContext.ENGINE_SCOPE);
                sanitizeBindings(cached);
                if (!allowExitFunctions) {
                    sb.append("var quit=function(){};var exit=function(){};");
                }
                if (!allowPrintFunctions) {
                    sb.append("var print=function(){};var echo = function(){};");
                }
                if (!allowReadFunctions) {
                    sb.append("var readFully=function(){};").append("var readLine=function(){};");
                }
                if (!allowLoadFunctions) {
                    sb.append("var load=function(){};var loadWithNewGlobal=function(){};");
                }
                if (!allowGlobalsObjects) {
                    // Max 22nd of Feb 2018: I don't think these are strictly necessary since they are only available in scripting mode
                    sb.append("var $ARG=null;var $ENV=null;var $EXEC=null;");
                    sb.append("var $OPTIONS=null;var $OUT=null;var $ERR=null;var $EXIT=null;");
                }
                scriptEngine.eval(sb.toString());

                resetEngineBindings();

                engineAsserted = true;
            }
        }
        catch (final Exception e) {
            throw new RuntimeException(e);
        }
    }

private void resetEngineBindings() {
        final Bindings bindings = createBindings();
        sanitizeBindings(bindings);
        bindings.putAll(cached);
        scriptEngine.setBindings(bindings, ScriptContext.ENGINE_SCOPE);
    }

private void sanitizeBindings(Bindings bindings) {
        if (!allowExitFunctions) {
            bindings.remove("quit");
            bindings.remove("exit");
        }
        if (!allowPrintFunctions) {
            bindings.remove("print");
            bindings.remove("echo");
        }
        if (!allowReadFunctions) {
            bindings.remove("readFully");
            bindings.remove("readLine");
        }
        if (!allowLoadFunctions) {
            bindings.remove("load");
            bindings.remove("loadWithNewGlobal");
        }
    }

@Override
	public Object eval(final String js) throws ScriptCPUAbuseException, ScriptException {
		return eval(js, null,null);
	}

@Override
	public Object eval(final String js) throws ScriptCPUAbuseException, ScriptException {
		return eval(js, null,null);
	}

private Bindings secureBindings(Bindings bindings) {
        if (bindings == null)
            return null;

        bindings.putAll(cached);

        return bindings;
    }

private Object executeSandboxedOperation(ScriptEngineOperation op) throws ScriptCPUAbuseException, ScriptException {
        assertScriptEngine();
		try {
			if (maxCPUTime == 0 && maxMemory == 0) {
				return op.executeScriptEngineOperation(scriptEngine);
			}
			checkExecutorPresence();
			final JsEvaluator evaluator = getEvaluator(op);
			executor.execute(evaluator);
			evaluator.runMonitor();
			if (evaluator.isCPULimitExceeded()) {
				throw new ScriptCPUAbuseException(
						"Script used more than the allowed [" + maxCPUTime + " ms] of CPU time.",
						evaluator.isScriptKilled(), evaluator.getException());
			} else if (evaluator.isMemoryLimitExceeded()) {
				throw new ScriptMemoryAbuseException(
						"Script used more than the allowed [" + maxMemory + " B] of memory.",
						evaluator.isScriptKilled(), evaluator.getException());
			}
			if (evaluator.getException() != null) {
				throw evaluator.getException();
			}
			return evaluator.getResult();
		} catch (RuntimeException | ScriptException e) {
			throw e;
		} catch (final Exception e) {
			throw new RuntimeException(e);
		}
	}

private JsEvaluator getEvaluator(ScriptEngineOperation op) {
		return new JsEvaluator(scriptEngine, maxCPUTime, maxMemory, op);
	}

private void checkExecutorPresence() {
		if (executor == null) {
			throw new IllegalStateException("When a CPU time or memory limit is set, an executor "
					+ "needs to be provided by calling .setExecutor(...)");
		}
	}

@Override
	public void setMaxCPUTime(final long limit) {
		maxCPUTime = limit;
	}

@Override
	public void setMaxMemory(final long limit) {
		maxMemory = limit;
	}

JsSanitizer getSanitizer() {
		if (sanitizer == null) {
			if (suppliedCache == null) {
				sanitizer = new JsSanitizer(scriptEngine, maxPreparedStatements, allowNoBraces);
			} else {
				sanitizer = new JsSanitizer(scriptEngine, allowNoBraces, suppliedCache);
			}
		}
		return sanitizer;
	}

@Override
	public void allow(final Class<?> clazz) {
		sandboxClassFilter.add(clazz);
	}

@Override
	public void setExecutor(final ExecutorService executor) {
		this.executor = executor;
	}

@Override
	public Object get(final String variableName) {
		return scriptEngine.get(variableName);
	}

@Override
	public void allowNoBraces(final boolean v) {
		if (allowNoBraces != v) {
			sanitizer = null;
		}
		allowNoBraces = v;
	}

@Override
	public void setMaxPreparedStatements(final int max) {
		if (maxPreparedStatements != max) {
			sanitizer = null;
		}
		maxPreparedStatements = max;
	}

@Override
	public Bindings createBindings() {
		return scriptEngine.createBindings();
	}

public LinkedHashMapSecuredJsCache(LinkedHashMap<String, String> linkedHashMap, boolean allowNoBraces) {
		this.map = linkedHashMap;
		this.allowNoBraces = allowNoBraces;
	}

@Override
	public String getOrCreate(String js, boolean allowNoBraces, Supplier<String> producer) {
		assertConfiguration(allowNoBraces);
		String result = map.get(js);
		if (result == null) {
			result = producer.get();
			map.put(js, result);
		}
		return result;
	}

private void assertConfiguration(boolean allowNoBraces) {
		if (allowNoBraces != this.allowNoBraces) {
			throw new IllegalArgumentException("Non-matching cache configuration");
		}
	}

public static String perform(String s) {
		String out = "";
		int mod = DEFAULT;
		for (int i = 0; i < s.length(); i++) {
			String substring = s.substring(i, Math.min(i + 2, s.length()));
			char c = s.charAt(i);
			switch (mod) {
			case DEFAULT: // default
				mod = substring.equals("/*") ? MULTI_LINE
						: substring.equals("//") ? ONE_LINE : c == '"' || c =='\'' ? STRING : DEFAULT;
				break;
			case STRING: // string
				mod = c == '"' || c == '\'' ? DEFAULT : c == '\\' ? ESCAPE : STRING;
				break;
			case ESCAPE: // string
				mod = STRING;
				break;
			case ONE_LINE: // one line comment
				mod = c == '\n' ? DEFAULT : ONE_LINE;
				continue;
			case MULTI_LINE: // multi line comment
				mod = substring.equals("*/") ? DEFAULT : MULTI_LINE;
				i += mod == DEFAULT ? 1 : 0;
				continue;
			}
			out += mod < 4 ? c : "";
		}

		return out;
	}

PoisonPil(final Pattern pattern, final String replacement) {
			this.pattern = pattern;
			this.replacement = replacement;
		}

@Override
  public boolean exposeToScripts(final String className) {
    return stringCache.contains(className);
  }

public void add(final Class<?> clazz) {
    allowed.add(clazz);
    stringCache.add(clazz.getName());
  }

public SandboxClassFilter() {
    allowed = new HashSet<>();
    stringCache = new HashSet<>();
  }

public EvaluateOperation(String js, ScriptContext scriptContext, Bindings bindings) {
        this.js = js;
        this.scriptContext = scriptContext;
        this.bindings = bindings;
    }

@Override
    public Object executeScriptEngineOperation(ScriptEngine scriptEngine) throws ScriptException {
        if (LOG.isDebugEnabled()) {
            LOG.debug("--- Running JS ---");
            LOG.debug(js);
            LOG.debug("--- JS END ---");
        }

        if (bindings != null) {
            return scriptEngine.eval(js, bindings);
        } else if (scriptContext != null) {
            return scriptEngine.eval(js, scriptContext);
        } else {
            return scriptEngine.eval(js);
        }
    }
